    customerId: 'CU-517063',
    confidence: 69,
    reason: 'Wrong-item claim on order with sealed-tote scan match',
    refund: '\u20B9870',
    decision: 'Pending review',
  },
];

function getConfidenceColor(confidence: number): string {
  if (confidence >= 85) return '#ef4444';
  if (confidence >= 60) return '#f59e0b';
  return '#22c55e';
}

function getDecisionClass(decision: string): string {
  switch (decision) {
    case 'Pending review':
      return 'decision--pending';
    case 'Escalated':
      return 'decision--escalated';
    case 'Denied':
      return 'decision--denied';
    case 'Approved':
      return 'decision--approved';
    default:
      return '';
  }
}

function FraudApp() {
  const [elapsed, setElapsed] = useState(10);

  useEffect(() => {
    const interval = setInterval(() => {
      setElapsed((prev) => prev + 1);
    }, 1000);
    return () => clearInterval(interval);
  }, []);

  return (
    <div className="fraud-app">
      <NavHeader />
      <main className="fraud-main">
        <div className="fraud-page-header">
          <div className="fraud-page-header__left">
            <span className="fraud-page-header__eyebrow">Risk &amp; Trust review queue</span>
            <h1 className="fraud-page-header__title">Fraud &amp; AI review</h1>
            <p className="fraud-page-header__subtitle">
              Model refund-abuse-v4 · scored 8,214 complaints in last 24h · 946 flagged for human review
            </p>
          </div>
          <div className="fraud-page-header__right">
            <span className="fraud-live-pill">
              <span className="fraud-live-pill__dot"></span>
              Updated {elapsed}s ago · LIVE
            </span>
          </div>
        </div>

        <div className="fraud-kpi-row">
          <div className="fraud-kpi-card">
            <span className="fraud-kpi-card__label">HIGH RISK COMPLAINTS</span>
            <span className="fraud-kpi-card__value fraud-kpi-card__value--red">214</span>
            <span className="fraud-kpi-card__caption">confidence &gt;= 85%, awaiting decision</span>
          </div>
          <div className="fraud-kpi-card">
            <span className="fraud-kpi-card__label">AVG AI CONFIDENCE</span>
            <span className="fraud-kpi-card__value">87.3 %</span>
            <span className="fraud-kpi-card__caption">on flagged population</span>
          </div>
          <div className="fraud-kpi-card">
            <span className="fraud-kpi-card__label">FLAGGED REFUND REQUESTS</span>
            <span className="fraud-kpi-card__value fraud-kpi-card__value--amber">{'\u20B9'}18.4L</span>
            <span className="fraud-kpi-card__caption">across 946 claims</span>
            <span className="fraud-kpi-card__caption">value held pending review</span>
          </div>
          <div className="fraud-kpi-card">
            <span className="fraud-kpi-card__label">REPEAT OFFENDERS</span>
            <span className="fraud-kpi-card__value">63</span>
            <span className="fraud-kpi-card__caption">3+ upheld flags in 90 days</span>
          </div>
        </div>

        <div className="fraud-table-section">
          <div className="fraud-table-header">
            <div className="fraud-table-header__left">
              <h2 className="fraud-table-header__title">AI-flagged complaints</h2>
              <p className="fraud-table-header__subtitle">
                Each row shows the model's confidence and the evidence behind the flag. Decide: approve, escalate or deny.
              </p>
            </div>
            <div className="fraud-table-header__right">
              <span className="fraud-model-pill">Model refund-abuse-v4 · precision 0.91</span>
            </div>
          </div>

          <div className="fraud-table-wrapper">
            <table className="fraud-table">
              <thead>
                <tr>
                  <th>COMPLAINT</th>
                  <th>CUSTOMER</th>
                  <th>AI CONFIDENCE</th>
                  <th>REASON FOR FLAG</th>
                  <th>REFUND</th>
                  <th>DECISION</th>
                </tr>
              </thead>
              <tbody>
                {COMPLAINTS.map((row) => (
                  <tr key={row.complaintId}>
                    <td>
                      <span className="fraud-table__primary">{row.complaintId}</span>
                      <span className="fraud-table__secondary">{row.storeId}</span>
                    </td>
                    <td>
                      <span className="fraud-table__primary">{row.customerName}</span>
                      <span className="fraud-table__secondary">{row.customerId}</span>
                    </td>
                    <td>
                      <div className="fraud-confidence">
                        <span
                          className="fraud-confidence__badge"
                          style={{ backgroundColor: getConfidenceColor(row.confidence) + '1a', color: getConfidenceColor(row.confidence) }}
                        >
                          {row.confidence}%
                        </span>
                        <div className="fraud-confidence__bar-track">
                          <div
                            className="fraud-confidence__bar-fill"
                            style={{ width: `${row.confidence}%`, backgroundColor: getConfidenceColor(row.confidence) }}
                          ></div>
                        </div>
                      </div>
                    </td>
                    <td>
                      <span className="fraud-table__reason">&ldquo;{row.reason}&rdquo;</span>
                    </td>
                    <td>
                      <span className="fraud-table__refund">{row.refund}</span>
                    </td>
                    <td>
                      <div className="fraud-decision-cell">
                        <span className={`fraud-decision-badge ${getDecisionClass(row.decision)}`}>
                          {row.decision}
                        </span>
                        {row.decision === 'Pending review' && (
                          <div className="fraud-action-buttons">
                            <button className="fraud-action-btn fraud-action-btn--approve">Approve</button>
                            <button className="fraud-action-btn fraud-action-btn--escalate">Escalate</button>
                            <button className="fraud-action-btn fraud-action-btn--deny">Deny</button>
                          </div>
                        )}
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      </main>
    </div>
  );
}

export default FraudApp;
